class JPEGSerializer(Serializer):
    """The JPEGSerializer serialize and deserialize JPEG image to and from bytes."""

    def serialize(self, item: Image) -> Tuple[bytes, Optional[str]]:

        if not isinstance(item, JpegImageFile):
            if Image is not None and isinstance(item, Image.Image) and item.mode == 'RGB':
                item = item.convert('RGB')
                item.save('temp.jpg', format='JPEG')
                item = Image.open('temp.jpg')
            else:
                return (), 'Unsupported image format.'

        if item.filename is not None and os.path.exists(item.filename):
            with open(item.filename, 'rb') as file:
                return file.read(), None

        return item.tobytes(), None
