        self._dtype_to_indices = {v: k for k, v in _NUMPY_DTYPE_MAPPING.items()}
        self._dtype: Optional[np.dtype] = None

    def setup(self, data_format: str) -> None:
        self._dtype = _NUMPY_DTYPE_MAPPING[int(data_format.split(":")[1])]

    def deserialize(self, data: bytes) -> np.ndarray:
        # Ensure _dtype is set
        assert self._dtype

        # Deserialize the given bytes data into a NumPy array
        dtype = self._dtype
        shape_size = np.frombuffer(data[4:8], np.uint32).item()
        shape = []
        for shape_idx in range(shape_size):
            shape.append(np.frombuffer(data[8 + 4 * shape_idx : 8 + 4 * (shape_idx + 1)], np.uint32).item())
        tensor = np.frombuffer(data[8 + 4 * (shape_idx + 1) : len(data)], dtype=dtype)
        shape = tuple(shape)
        if tensor.shape == shape:
            return tensor
        return np.reshape(tensor, shape)

